import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Fingerprint, Cpu, Shield, Zap, CircleDot } from 'lucide-react';

const SignIn = ({ onLogin }) => {
  const [loading, setLoading] = useState(false);

  const handleAuth = (e) => {
    e.preventDefault();
    setLoading(true);
    // Mimicking high-speed system handshake
    setTimeout(() => onLogin(), 1800);
  };

  return (
    <div className="h-screen w-full bg-[#FDFAD8] flex items-center justify-center overflow-hidden relative">

      {/* --- AMBIENT NEO-LIGHTS (No Black, just colored energy) --- */}
      <motion.div 
        animate={{ 
          scale: [1, 1.2, 1],
          x: [0, 50, 0],
          y: [0, 30, 0]
        }}
        transition={{ duration: 10, repeat: Infinity, ease: "easeInOut" }}
        className="absolute top-[-20%] left-[-10%] w-[600px] h-[600px] bg-[#CAD23C]/30 rounded-full blur-[120px]"
      />
      <motion.div 
        animate={{ 
          scale: [1, 1.3, 1],
          x: [0, -40, 0],
          y: [0, -60, 0]
        }}
        transition={{ duration: 12, repeat: Infinity, ease: "easeInOut" }}
        className="absolute bottom-[-10%] right-[-5%] w-[500px] h-[500px] bg-[#47510B]/10 rounded-full blur-[100px]"
      />

      {/* --- THE MAIN GLASS TERMINAL --- */}
      <motion.div 
        initial={{ opacity: 0, scale: 0.9, y: 30 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1] }}
        className="relative z-10 w-full max-w-[420px] bg-white/40 backdrop-blur-2xl rounded-[50px] p-10 border border-white shadow-[0_40px_100px_-20px_rgba(71,81,11,0.15)]"
      >

        {/* LOGO SECTION */}
        <div className="flex flex-col items-center mb-12">
          <div className="relative mb-6">
            <motion.div 
              animate={{ rotate: 360 }}
              transition={{ duration: 15, repeat: Infinity, ease: "linear" }}
              className="absolute -inset-4 border-2 border-dashed border-[#47510B]/10 rounded-full"
            />
            <div className="w-20 h-20 bg-[#47510B] rounded-3xl flex items-center justify-center shadow-2xl shadow-[#47510B]/30 relative z-10">
              <Cpu className="text-[#CAD23C]" size={32} strokeWidth={1.5} />
            </div>
          </div>
          <h1 className="text-4xl font-[1000] italic text-[#47510B] uppercase tracking-tighter leading-none text-center">
            Vanguard <br/> <span className="text-[#FF5B03]">Command.</span>
          </h1>
          <p className="mt-3 text-[10px] font-black text-[#47510B]/40 uppercase tracking-[0.5em]">Security_Clearance_v.4</p>
        </div>

        {/* INTERACTIVE FORM */}
        <form onSubmit={handleAuth} className="space-y-6">
          <div className="space-y-4">
            <div className="relative group">
              <input 
                required
                type="text"
                placeholder="OPERATOR_ID"
                className="w-full bg-white/60 border-2 border-transparent focus:border-[#47510B]/10 p-5 rounded-2xl text-[#47510B] font-black tracking-widest outline-none transition-all placeholder-[#47510B]/20 text-sm"
              />
              <div className="absolute right-5 top-1/2 -translate-y-1/2 text-[#47510B]/20 group-focus-within:text-[#47510B] transition-colors">
                <CircleDot size={18} />
              </div>
            </div>

            <div className="relative group">
              <input 
                required
                type="password"
                placeholder="ACCESS_KEY"
                className="w-full bg-white/60 border-2 border-transparent focus:border-[#47510B]/10 p-5 rounded-2xl text-[#47510B] font-black tracking-widest outline-none transition-all placeholder-[#47510B]/20 text-sm"
              />
              <div className="absolute right-5 top-1/2 -translate-y-1/2 text-[#47510B]/20 group-focus-within:text-[#47510B] transition-colors">
                <Shield size={18} />
              </div>
            </div>
          </div>

          <motion.button
            whileHover={{ scale: 1.02, y: -2 }}
            whileTap={{ scale: 0.98 }}
            className="w-full bg-[#47510B] text-white p-6 rounded-2xl flex items-center justify-between group shadow-xl shadow-[#47510B]/20 relative overflow-hidden"
          >
            <AnimatePresence mode="wait">
              {loading ? (
                <motion.div 
                  key="L" initial={{ opacity: 0 }} animate={{ opacity: 1 }}
                  className="w-full flex justify-center"
                >
                  <div className="w-6 h-6 border-4 border-[#CAD23C]/30 border-t-[#CAD23C] rounded-full animate-spin" />
                </motion.div>
              ) : (
                <>
                  <span className="font-black italic uppercase tracking-widest text-lg">Initialize</span>
                  <div className="flex items-center gap-2">
                    <div className="h-px w-8 bg-[#CAD23C]/30" />
                    <Fingerprint className="text-[#CAD23C]" size={24} />
                  </div>
                </>
              )}
            </AnimatePresence>

            {/* Glossy sweep effect */}
            <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent -translate-x-full group-hover:translate-x-full transition-transform duration-700" />
          </motion.button>
        </form>

        {/* BOTTOM HUD BITS */}
        <div className="mt-10 flex justify-between items-center px-2">
          <div className="flex gap-3">
            <Zap size={16} className="text-[#FF5B03]" />
            <div className="h-4 w-px bg-[#47510B]/10" />
            <span className="text-[9px] font-black text-[#47510B]/40 uppercase tracking-widest">Node_72</span>
          </div>
          <span className="text-[9px] font-black text-[#47510B]/40 uppercase tracking-widest">Encrypted_Line</span>
        </div>
      </motion.div>

      {/* DECORATIVE CORNER MARKS */}
      <div className="absolute top-10 left-10 w-20 h-20 border-t-2 border-l-2 border-[#47510B]/5" />
      <div className="absolute bottom-10 right-10 w-20 h-20 border-b-2 border-r-2 border-[#47510B]/5" />
    </div>
  );
};

export default SignIn;
